import{_ as e,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"精准拉伸","description":"从目标肌群、动作控制、呼吸和训练安排理解拉伸读物，不把拉伸等同于所有疼痛的治疗。","frontmatter":{"title":"精准拉伸","description":"从目标肌群、动作控制、呼吸和训练安排理解拉伸读物，不把拉伸等同于所有疼痛的治疗。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 运动与健康","summary":"从目标肌群、动作控制、呼吸和训练安排理解拉伸读物，不把拉伸等同于所有疼痛的治疗。","status":"active","related":[{"title":"肌肉力量训练 彩色图谱","link":"/life/personal/books/growth/strength-training","kind":"书籍导读","scope":"general","audience":"general"},{"title":"从零开始学游泳","link":"/life/personal/books/growth/swimming","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"肌肉力量训练 彩色图谱","link":"/life/personal/books/growth/strength-training"},"next":{"text":"从零开始学游泳","link":"/life/personal/books/growth/swimming"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"肌肉力量训练 彩色图谱","link":"/life/personal/books/growth/strength-training"},"next":{"text":"从零开始学游泳","link":"/life/personal/books/growth/swimming"}},"headers":[],"relativePath":"life/personal/books/growth/stretching.md","filePath":"life/personal/books/growth/stretching.md"}'),n={name:"life/personal/books/growth/stretching.md"};function i(l,t,s,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="精准拉伸" tabindex="-1">精准拉伸 <a class="header-anchor" href="#精准拉伸" aria-label="Permalink to &quot;精准拉伸&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 运动与健康。</strong> 这本书在书单中用于学习拉伸方法和身体活动能力。阅读重点可以放在识别动作目标、理解身体位置、控制强度，以及把拉伸放进完整的运动安排。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《精准拉伸》：可核书目作者为克里斯蒂安·博格（Kristian Berg）。</strong> <a href="https://opac.lib.uibe.edu.cn/opac/book/1c91884d30ff559b8733e20adc49063d" target="_blank" rel="noopener noreferrer">对外经济贸易大学图书馆</a>列出2022年人民邮电出版社版、王雄和杨斌译、ISBN 9787115579591，对应 <em>Prescriptive Stretching</em>。<a href="https://us.humankinetics.com/products/prescriptive-stretching-2nd-edition" target="_blank" rel="noopener noreferrer">英文出版社Human Kinetics</a>介绍其naprapathy手法治疗背景；不同地区执业制度不同，本页不简单等同于国内临床医生资格，也不把出版宣传中的疗效作为本站结论。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合希望读懂拉伸图示、肌群名称和动作说明的运动爱好者。此页用于评价和组织阅读，不能由书中的某个动作推断读者疼痛的原因或适用方案。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>已核到博格著的人民邮电出版社版本；<a href="https://aijiaocai.com/textbook/details?textbook_id=924969" target="_blank" rel="noopener noreferrer">2016年版书目</a>ISBN为9787115421326，2022年版为9787115579591，用户版次仍待确认。<strong>以下为本站主题导读，不是原书目录。</strong> 不从中文题名推定个体诊断或治疗效果。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>主要内容</th><th>实践时的关注点</th></tr></thead><tbody><tr><td>拉伸的目的</td><td>区分活动范围、运动准备、训练后的舒适感等不同目标。</td><td>先说明为什么做这个动作，再选择方法。</td></tr><tr><td>肌群与身体位置</td><td>理解目标区域和相邻关节如何共同影响感觉。</td><td>是否通过扭转、塌腰等代偿换取更大幅度。</td></tr><tr><td>动态与静态方法</td><td>认识移动中的活动练习和保持姿势的不同特点。</td><td>依据活动安排和自身情况选择，不机械套用同一流程。</td></tr><tr><td>强度与呼吸</td><td>在可控范围内观察感觉，避免憋气和强行追求幅度。</td><td>尖锐疼痛、麻木等不应被当成“拉开了”的信号。</td></tr><tr><td>上下肢与躯干</td><td>按实际需要组织肩、髋、腿部等区域的练习。</td><td>哪个区域限制了当前动作，是否还有力量与控制问题。</td></tr><tr><td>记录与调整</td><td>用稳定的姿势和条件比较变化。</td><td>活动能力是否改善，是否出现不适或过度疲劳。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 拉伸容易被理解为幅度越大越好，但活动范围只是身体能力的一部分。能到达某个位置，还需要在那个范围内保持控制。阅读这类书时，把动作目的、感受和适用条件一起记录，比只收集“哪里紧就拉哪里”的动作更有价值。</p><p>拉伸读物可以帮助理解身体与安排练习。持续疼痛、麻木或受伤后的问题，则需要结合专业评估，不能从一张肌肉图直接推断原因。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 一个动作的名称与图像，并不能独立说明它为什么适合某个人。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 读一个动作时，同时记录目标部位、作者解释、适用前提及未说明的问题。把文字与解剖图交叉核对，检视自己是否把位置感受当成诊断；形成的是阅读动作说明的能力，而非自行制定治疗方案。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>按部位查找方便，但容易从哪里不舒服直接跳到动作，略过适用条件；版本间附册与编排也需核实。<strong>推荐语：</strong> 可作为拉伸术语与图示参考读物，涉及疗效的主张另看证据，不用“精准”一词替代判断。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://search.worldcat.org/search?q=%E7%B2%BE%E5%87%86%E6%8B%89%E4%BC%B8" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：用于核对作者、版本及目录，当前未确认具体书目。</li><li>实物核对时应特别查看禁忌、动作前提与适用人群，不能只保留动作名称。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const b=e(n,[["render",i]]);export{g as __pageData,b as default};
